import React from 'react';

const Header = () => {
    return (
        <header>
            <h1>Recordar para defender la democracia</h1>
            <nav>
                <ul>
                    <li><a href="#hero">Inicio</a></li>
                    <li><a href="#contexto-historico">Contexto Histórico</a></li>
                    <li><a href="#timeline">Línea de Tiempo</a></li>
                    <li><a href="#importancia">¿Por qué importa hoy?</a></li>
                    <li><a href="#propuesta-innovadora">Propuesta Innovadora</a></li>
                    <li><a href="#publico-objetivo">Público Objetivo</a></li>
                    <li><a href="#triple-helice">Triple Hélice</a></li>
                    <li><a href="#cuadruple-helice">Cuádruple Hélice</a></li>
                    <li><a href="#aporte-desarrollo">Aporte al Desarrollo</a></li>
                    <li><a href="#aprendizajes">Aprendizajes Obtenidos</a></li>
                    <li><a href="#conclusion">Conclusión</a></li>
                </ul>
            </nav>
        </header>
    );
};

export default Header;
